function worldPointer(e){let y=((e.clientY-oy)/(scale*zoom)+camY)/.78,x=(e.clientX-ox)/(scale*zoom*horizontalScale)+camX+y*.34;return{x:Math.max(-245,Math.min(235,x)),y:Math.max(-220,Math.min(395,y))}}
function moveHero(e){let p=worldPointer(e);hero.tx=p.x;hero.ty=p.y}
canvas.addEventListener('pointerdown',e=>{if(paused||!playing)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture?.(e.pointerId);if(pointers.size===2){let [a,b]=[...pointers.values()];pinchDistance=Math.hypot(a.x-b.x,a.y-b.y);dragging=false;return}if(trapArmed){let p=worldPointer(e),cost={spikes:35,mud:30,barrel:45}[trapArmed];if(Math.hypot(point(nearestPath(p.x,p.y)).x-p.x,point(nearestPath(p.x,p.y)).y-p.y)>40){message('Ловушка должна стоять на дороге');return}if(state.gold>=cost&&traps.filter(t=>!t.used).length<12){state.gold-=cost;traps.push({...p,kind:trapArmed,radius:trapArmed==='mud'?45:28,cd:0});save();message('Ловушка установлена')}trapArmed=null;return}if(armed){armed=false;cool=20*(1-meta.focus*.06);let p=worldPointer(e);abilityFX.push({x:p.x,y:p.y,kind:'fire',life:1.2,max:1.2});burst(p.x,p.y,'#ff974e',60);enemies.forEach(v=>{if(Math.hypot(v.x-p.x,v.y-p.y)<95)hit(v,110+state.level*20)});beep(90);return}let spot=worldPointer(e),chosen=buildings.find(b=>b.built&&b.id!=='barracks'&&Math.hypot(b.x-spot.x,b.y-spot.y)<40);selectedBuilding=chosen?chosen.id:null;if(chosen){message(chosen.name+(['archer','cannon'].includes(chosen.id)?' · радиус атаки · настройка в меню':' · выбрана'));return}dragging=true;canvas.setPointerCapture?.(e.pointerId);moveHero(e)});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){let[a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinchDistance>0)zoom=Math.max(.8,Math.min(2,d/pinchDistance*zoom));pinchDistance=d;return}if(dragging&&!paused&&playing)moveHero(e)});function endPointer(e){pointers.delete(e.pointerId);dragging=false;pinchDistance=0}canvas.addEventListener('pointerup',endPointer);canvas.addEventListener('pointercancel',endPointer);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){paused=true;$('pause').textContent='▶';save()}});window.addEventListener('pagehide',save);
function frame(t){let dt=Math.min((t-last)/1000,.04);last=t;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
